import type { Q } from "../types";

export const ibPart1: Q[] = [
  { t: "Depreciation flowing through the three statements", p: "Walk me through how an extra 10 of depreciation expense affects the income statement, cash flow statement and balance sheet, assuming a 25 percent tax rate.", d: 1, tp: "ib-accounting", i: "On the income statement, pre-tax income falls by 10 and, at 25 percent tax, net income falls by 7.5. On the cash flow statement, net income is down 7.5 but depreciation is a non-cash charge added back (+10), so cash from operations rises by 2.5 because of the lower tax bill. On the balance sheet, PP&E falls by 10 and cash rises by 2.5, so assets fall by 7.5, matching the 7.5 drop in retained earnings. The only cash effect is the tax saving.", c: ["Pre-tax income falls by the full 10", "Net income falls by 10 x (1 - tax rate)", "Depreciation is added back as a non-cash item", "Cash rises only through the tax shield"], k: ["Both sides of the balance sheet change by 7.5", "Depreciation shields tax but is not itself a cash outflow"], m: ["Thinking depreciation reduces cash by 10", "Forgetting the tax effect"] },
  { t: "Why EBITDA is not cash flow", p: "A company reports strong EBITDA but is burning cash. Explain the items that can drive a gap between EBITDA and actual cash flow.", d: 1, tp: "ib-accounting", tp2: "ib-valuation", i: "EBITDA ignores several real cash uses: capital expenditures needed to maintain or grow the asset base, cash interest on debt, cash taxes, increases in net working capital (receivables and inventory growing faster than payables), and one-off or restructuring costs. It also ignores lease and pension payments depending on the accounting regime. Free cash flow is EBITDA less these items, so a growing or capital-intensive company can show high EBITDA and still have negative cash flow.", c: ["Capital expenditures are excluded from EBITDA", "Working capital investment consumes cash", "Cash interest and taxes sit below EBITDA", "Non-recurring and restructuring cash costs"], k: ["EBITDA is a proxy for operating profit before capital intensity", "Capital-intensive firms are most misleadingly flattered by EBITDA"], m: ["Treating EBITDA as equivalent to operating cash flow", "Ignoring working capital"] },
  { t: "Inventory purchase paid in cash", p: "A company buys 50 of inventory for cash. Which statements change, and how?", d: 1, tp: "ib-accounting", i: "The income statement is unaffected at the time of purchase because inventory is an asset, not an expense; the cost only hits the income statement as cost of goods sold when the goods are sold. On the balance sheet, inventory rises by 50 and cash falls by 50, so total assets are unchanged. On the cash flow statement, the increase in inventory is a 50 use of cash within the working capital section of cash from operations.", c: ["Inventory is capitalised as an asset", "No income statement impact until sale", "Asset swap between cash and inventory", "Inventory increase is a use of operating cash"], k: ["Timing of expense recognition differs from timing of cash", "Cash flow statement captures the working capital change"], m: ["Expensing the purchase immediately", "Putting the purchase in investing activities"] },
  { t: "Linking the three statements", p: "Describe in your own words how the income statement, balance sheet and cash flow statement connect to each other.", d: 1, tp: "ib-accounting", i: "Net income from the income statement is the starting point of cash from operations and also increases retained earnings on the balance sheet (less dividends). The cash flow statement is built from changes in balance sheet items: working capital accounts drive operating cash flow, PP&E and acquisitions drive investing, and debt, equity and dividends drive financing. The ending cash from the cash flow statement becomes the cash line on the balance sheet, which is what ensures the balance sheet balances.", c: ["Net income feeds retained earnings and cash flow", "Cash flow derives from balance sheet changes", "Ending cash flows to the balance sheet", "Operating, investing and financing sections"], k: ["The balance sheet balancing is a check on model integrity", "Each transaction has at least two linked effects"], m: ["Thinking the statements are independent", "Treating dividends as an expense"] },
  { t: "Accounting for deferred revenue", p: "A software company collects 120 upfront for a 12-month subscription. How is this recorded at signing and over the year?", d: 1, tp: "ib-accounting", i: "At signing cash rises by 120 and a deferred revenue liability of 120 is created, because the service has not yet been delivered; no revenue is recognised. Each month, 10 of deferred revenue is released into revenue on the income statement, reducing the liability. Cash flow from operations captures the full 120 upfront through the increase in deferred revenue, so cash flow runs ahead of reported revenue and profit in a growing subscription business.", c: ["Deferred revenue is a liability", "Revenue recognised as service is delivered", "Cash received upfront in operating cash flow", "Liability unwinds by 10 per month"], k: ["Cash and revenue timing differ", "Growing deferred revenue is a source of cash"], m: ["Booking all 120 as revenue on day one"] },
  { t: "Share repurchase on the statements", p: "A company uses 100 of cash to repurchase its own shares. Describe the effect on each financial statement.", d: 1, tp: "ib-accounting", i: "The income statement is not directly affected, since buybacks are not an expense, although interest income may fall slightly because there is less cash. On the balance sheet, cash falls by 100 and shareholders' equity falls by 100 through treasury stock, a contra-equity account. On the cash flow statement, the 100 appears as an outflow in financing activities. Shares outstanding fall, which can lift earnings per share even though net income does not rise.", c: ["Cash and equity both fall by the amount", "Treasury stock is contra-equity", "Financing cash outflow", "Share count falls and EPS can rise"], k: ["Buybacks are a return of capital, not an expense", "Foregone interest income is a second-order effect"], m: ["Recording the buyback as an expense", "Reducing assets without reducing equity"] },
  { t: "Capitalising versus expensing a cost", p: "What is the difference between capitalising and expensing a cost, and how does the choice change net income and cash flow?", d: 1, tp: "ib-accounting", i: "An expensed cost reduces net income immediately in the period incurred. A capitalised cost is recorded as an asset and then depreciated or amortised over its useful life, so profit is hit gradually. Capitalising raises current-period earnings and EBITDA versus expensing, but it does not change total cash spent. The cash outflow still occurs, in investing activities if capitalised rather than in operations if expensed, so capitalisation can make operating cash flow look better.", c: ["Expensed costs hit income immediately", "Capitalised costs become assets and depreciate", "Total cash is the same either way", "Capitalised spend shows in investing cash flow"], k: ["Aggressive capitalisation flatters EBITDA and operating cash flow", "Analysts compare firms on a consistent basis"], m: ["Believing capitalising reduces cash spent"] },
  { t: "Dividends on the statements", p: "How does paying a cash dividend of 40 appear across the three statements?", d: 1, tp: "ib-accounting", i: "Dividends do not appear on the income statement because they are a distribution of profit, not an expense. On the balance sheet, cash falls by 40 and retained earnings fall by 40. On the cash flow statement, the 40 is a financing outflow. Net income is unchanged, but the company has less cash and less retained equity, and interest income on that cash may drop in later periods.", c: ["No income statement effect", "Retained earnings decrease", "Cash decreases", "Financing activities outflow"], k: ["Distributions to owners are not costs of doing business", "Dividends change equity, not profit"], m: ["Expensing dividends through the income statement"] },
  { t: "Accrued expenses and cash flow", p: "If accounts payable increases by 30 over the period, what does that mean for cash flow, and why?", d: 1, tp: "ib-accounting", i: "An increase in accounts payable means the company recorded expenses or purchases that it has not yet paid, so cash was retained. In the cash flow statement this is a source of cash and is added within working capital adjustments in operating cash flow. Net income already deducted the expense, so the add-back of 30 reverses the non-cash portion. Stretching payables can flatter cash flow temporarily but unwinds when suppliers are paid.", c: ["Payables increase is a source of cash", "Expense was recognised but not yet paid", "Working capital adjustment in operations", "Unwinds when paid"], k: ["Liability increases add to cash flow, asset increases subtract", "Payables management is a liquidity lever"], m: ["Treating a payables increase as a use of cash"] },
  { t: "Deferred tax liability from accelerated depreciation", p: "A company depreciates an asset faster for tax than for book purposes. Explain what happens to taxes and the balance sheet.", d: 2, tp: "ib-accounting", i: "Faster tax depreciation lowers taxable income and cash taxes now, while book income, and so book tax expense, is higher. The difference is booked as a deferred tax liability. For example, tax depreciation of 100 versus book depreciation of 60 at 25 percent creates a DTL of 10, and cash taxes are 10 below book tax expense. The DTL increase is added in cash from operations. Over time the timing difference reverses, so the DTL shrinks and cash taxes exceed book taxes, unless the company keeps investing.", c: ["Timing difference between book and tax depreciation", "DTL equals difference times tax rate", "Cash taxes lower than book taxes initially", "DTL reverses as the asset ages"], k: ["A growing asset base can keep a DTL growing indefinitely", "The DTL is a source of cash in operating cash flow"], m: ["Thinking the company permanently avoids the tax"] },
  { t: "Goodwill creation in an acquisition", p: "Explain how goodwill is calculated and shown on the balance sheet when a company acquires another for more than its book value.", d: 2, tp: "ib-accounting", tp2: "ib-valuation", i: "Goodwill is the purchase price paid for equity less the fair value of net identifiable assets acquired. Assets are first written up to fair value (for example PP&E and intangibles), with a deferred tax liability set up for the write-ups, and the target's old goodwill is eliminated. If a target with book equity of 200 is bought for 500 with a 100 PP&E write-up and 25 percent tax, the DTL is 25, net identifiable assets are 275 and goodwill is 225. Goodwill sits on the buyer's balance sheet, is not amortised under US GAAP for public companies and is tested annually for impairment.", c: ["Price minus fair value of net identifiable assets", "Write-ups create a deferred tax liability", "Old goodwill is eliminated", "Annual impairment test instead of amortisation"], k: ["Goodwill is the residual", "The buyer's balance sheet absorbs the target's assets at fair value"], m: ["Goodwill is price minus book value only", "Amortising goodwill every year under US GAAP"] },
  { t: "Asset write-down effect on the statements", p: "A company writes down an asset by 100 and the write-down is tax deductible at 25 percent. Walk me through the three statements.", d: 2, tp: "ib-accounting", i: "The income statement shows a 100 impairment charge, so pre-tax income falls by 100, tax expense falls by 25 and net income falls by 75. On the cash flow statement, net income is down 75 but the 100 non-cash write-down is added back, so cash from operations rises by 25 from the lower taxes paid. On the balance sheet, the asset falls by 100 and cash rises by 25, so assets fall by 75, matching the 75 reduction in retained earnings. If the charge were not currently deductible, a deferred tax asset would be booked instead and cash would not change.", c: ["Impairment is a non-cash charge", "Net income falls by charge times (1 - tax)", "Added back in operating cash flow", "Cash rises only through the tax saving"], k: ["Non-deductible charges create a DTA, not cash", "Balance sheet remains balanced at minus 75 each side"], m: ["Believing a write-down consumes cash"] },
  { t: "Capitalised financing fees and original issue discount", p: "A company issues 500 of debt and pays 10 in financing fees. How are the fees accounted for?", d: 2, tp: "ib-accounting", i: "The company receives 490 net cash (or pays 10 separately), and the fees are capitalised rather than expensed, shown as a reduction of debt carrying value under US GAAP (an asset in older presentations). They are then amortised over the life of the debt as a non-cash component of interest expense. Each year's amortisation reduces net income and is added back in cash from operations, and the debt's carrying value accretes toward its 500 face value. Financing fees are reported in financing activities.", c: ["Fees capitalised, not expensed", "Amortised over the debt term", "Non-cash interest expense add-back", "Debt carrying value accretes to face"], k: ["Matching the cost to the period of the borrowing", "Early repayment can accelerate the write-off"], m: ["Expensing all fees on day one"] },
  { t: "Operating versus finance leases under modern standards", p: "How do operating and finance leases differ under US GAAP and how does IFRS 16 treat them?", d: 2, tp: "ib-accounting", tp2: "ib-valuation", i: "Under ASC 842 both types put a right-of-use asset and lease liability on the balance sheet. A finance lease is expensed as depreciation plus interest, so EBITDA excludes the cost. An operating lease has a single straight-line lease cost within operating expense, so EBITDA is after rent. IFRS 16 has no operating lease category for lessees: nearly all leases are treated like finance leases with depreciation and interest, which lifts EBITDA and adds lease debt. This matters for comparability and for whether lease liabilities belong in enterprise value.", c: ["Right-of-use asset and lease liability on balance sheet", "Finance lease: depreciation plus interest", "Operating lease: single straight-line cost in US GAAP", "IFRS 16 treats nearly all as finance-style"], k: ["EBITDA and net debt comparability depends on the standard", "Consistency between multiple and EV definition is essential"], m: ["Thinking operating leases are still off balance sheet under ASC 842"] },
  { t: "Five-step revenue recognition model", p: "Outline the five-step approach to revenue recognition under ASC 606 and give an example where it changes timing.", d: 2, tp: "ib-accounting", i: "The steps are identify the contract, identify the performance obligations, determine the transaction price, allocate the price to the obligations based on standalone selling prices, and recognise revenue when or as each obligation is satisfied. A software firm selling a licence, implementation and support in a bundle must split the price, recognising the licence at delivery, implementation as work is done and support ratably. This can accelerate or defer revenue compared with recognising on invoicing.", c: ["Identify the contract", "Identify performance obligations", "Determine and allocate the transaction price", "Recognise on satisfaction of each obligation"], k: ["Revenue follows transfer of control, not billing", "Bundles need standalone selling price allocation"], m: ["Recognising revenue when cash is received"] },
  { t: "Increase in accounts receivable", p: "Revenue is 200 and customers have paid only 150 in cash. How does that appear on the statements, and what does it imply for cash flow?", d: 2, tp: "ib-accounting", i: "The income statement records the full 200 of revenue. Accounts receivable rises by 50 on the balance sheet, because of the unpaid sales. In the cash flow statement, net income includes the 50 of uncollected revenue, so the increase in receivables is subtracted in working capital, giving a 50 reduction to operating cash flow relative to profit. Growing receivables can signal healthy growth or collection problems, and are tracked through days sales outstanding.", c: ["Revenue recognised on delivery regardless of cash", "Receivables are an asset that rises", "Subtracted in working capital adjustments", "DSO as a diagnostic"], k: ["Asset increases consume cash", "Rapid receivable growth requires scrutiny of quality of revenue"], m: ["Adding the receivable increase back to cash flow"] },
  { t: "PIK interest mechanics", p: "A company has payment-in-kind (PIK) debt. How does PIK interest flow through the statements?", d: 2, tp: "ib-accounting", i: "PIK interest is recorded as interest expense on the income statement, reducing net income and taxes just like cash interest, but it is not paid in cash. Instead it is added to the principal, so the debt balance grows. In the cash flow statement, PIK interest is added back as a non-cash item in operations, and on the balance sheet debt rises by the accrued amount. Cash is preserved in the near term, but leverage and the eventual repayment burden compound.", c: ["Interest expense is recognised", "Accrued interest added to principal", "Non-cash add-back in operating cash flow", "Debt balance accretes"], k: ["PIK preserves liquidity but increases leverage", "Tax deductibility is still available"], m: ["Thinking PIK interest is not an expense"] },
  { t: "Equity method versus consolidation", p: "When is a company's investment accounted for under the equity method rather than consolidated, and how does it show up in financials?", d: 2, tp: "ib-accounting", i: "Consolidation applies with control, generally over 50 percent ownership, and combines 100 percent of the subsidiary's assets, liabilities, revenue and expenses with a non-controlling interest for the rest. The equity method applies with significant influence, typically 20 to 50 percent. The investment sits as one balance sheet asset, increased by the investor's share of net income (shown below operating income) and reduced by dividends received. Share of income is non-cash and is adjusted in cash from operations, with dividends received being the actual cash.", c: ["Over 50 percent control means consolidation", "20 to 50 percent significant influence uses equity method", "Share of net income increases the investment", "Dividends reduce the investment and are cash"], k: ["Equity-method investments do not contribute to revenue or EBITDA", "Valuation requires adding the investment's value separately"], m: ["Recording the full subsidiary revenue under the equity method"] },
  { t: "Deferred tax asset from net operating losses", p: "A company generates a tax loss of 100 and the rate is 25 percent. How does the deferred tax asset arise and when might it be impaired?", d: 2, tp: "ib-accounting", i: "The loss is carried forward and can offset future taxable profit, so the company records a deferred tax asset of 25 (100 times 25 percent) and a matching tax benefit on the income statement. No cash comes in at that point. If it becomes unlikely the company will earn enough taxable profit to use the loss before expiry or other limits, a valuation allowance is recorded, reducing the DTA and increasing tax expense. Use of the NOL later reduces cash taxes and unwinds the asset.", c: ["Loss carryforward creates a DTA", "DTA equals loss times the tax rate", "Valuation allowance if use is not probable", "Reduces future cash taxes"], k: ["Recoverability depends on future profitability forecasts", "NOL usage can be limited after a change of control"], m: ["Thinking the tax benefit is received in cash immediately"] },
  { t: "Purchase accounting write-ups and deferred taxes", p: "In an acquisition where the buyer writes up the target's PP&E in a stock deal, why does a deferred tax liability arise and what happens to it over time?", d: 3, tp: "ib-accounting", i: "In a stock purchase the target's tax basis carries over, so a book write-up of PP&E is not matched by higher tax depreciation. The extra book depreciation is not deductible, creating a temporary difference, so a DTL equal to the write-up times the tax rate is recorded at closing and increases goodwill. As the written-up asset is depreciated, book expense is higher than tax, and the DTL unwinds, reducing book tax expense relative to cash taxes. Cash taxes are unchanged by the write-up. In an asset sale or 338(h)(10) election, basis steps up and no DTL arises.", c: ["Stock deal keeps tax basis", "Write-up times tax rate equals DTL", "DTL increases goodwill", "DTL unwinds as written-up asset depreciates"], k: ["Book-tax basis difference drives deferred tax", "Asset deals and 338(h)(10) change the tax outcome"], m: ["Believing the write-up gives extra cash tax deductions in a stock deal"] },
  { t: "Stock-based compensation across the statements", p: "How is stock-based compensation treated in the three statements and how should an analyst treat it in EBITDA and free cash flow?", d: 3, tp: "ib-accounting", tp2: "ib-valuation", i: "SBC is an operating expense on the income statement, reducing net income, but non-cash, so it is added back in cash from operations and credited to additional paid-in capital within equity. Many companies report adjusted EBITDA excluding SBC and show higher free cash flow as a result. However the cost is real: it is paid in shares that dilute owners or must be offset with cash buybacks. For valuation, treating SBC as an operating cost (not adding it back) or explicitly modelling dilution avoids overstating value.", c: ["Expense reduces net income", "Non-cash add-back in operating cash flow", "Credited to APIC in equity", "Real economic cost through dilution"], k: ["Adjusted EBITDA and FCF are flattered by excluding SBC", "Consistency between dilution and cash treatment matters"], m: ["Calling SBC free because it is non-cash"] },
  { t: "Debt paydown and the interest circularity", p: "A company uses 80 of excess cash to repay debt. Explain the immediate effects and why this causes a circularity in a financial model.", d: 3, tp: "ib-accounting", i: "Cash falls by 80 and debt falls by 80, so assets and liabilities decline equally and nothing changes on the income statement immediately; the cash flow statement shows an 80 financing outflow. In later periods interest expense is lower, raising net income and cash flow. If interest is calculated on average debt balances, interest depends on ending debt, which depends on cash available for repayment, which depends on net income, which depends on interest: a circular reference. Models handle it with iterative calculation, a circuit-breaker toggle, or by using beginning balances.", c: ["Cash and debt both fall", "Financing outflow", "Lower future interest expense", "Average balance interest creates circularity"], k: ["Interest to net income to cash to repayment loop", "Beginning balance interest removes the circularity at some accuracy cost"], m: ["Thinking the paydown immediately changes net income"] },
  { t: "Goodwill impairment mechanics", p: "A company impairs 150 of goodwill. What happens on each statement and does it affect cash taxes?", d: 3, tp: "ib-accounting", i: "The income statement shows a 150 non-cash impairment charge, reducing operating and pre-tax income. On the balance sheet goodwill falls by 150 and retained earnings fall by 150 less any tax effect. The cash flow statement adds the charge back, so there is no cash impact apart from taxes. Goodwill from a stock deal is generally not tax deductible, so no tax shield arises and net income falls by close to the full 150. Under both US GAAP and IFRS a goodwill impairment cannot later be reversed.", c: ["Non-cash charge", "Goodwill reduced on balance sheet", "Added back in cash flow", "Usually no tax deduction and no reversal"], k: ["Impairment signals the acquisition underperformed", "Impairment is excluded from adjusted EBITDA but reflects past capital allocation"], m: ["Thinking impairment uses cash", "Assuming the write-down creates a tax saving"] },
  { t: "Troubleshooting a balance sheet that does not balance", p: "Your three-statement model has a balance sheet that is out by exactly 20. How would you track down the error?", d: 3, tp: "ib-accounting", i: "First check whether the imbalance is stable or changing across periods, since a one-time difference points to the opening balance sheet or the first projection year. A difference of 20 equal to twice 10 suggests a sign error, because flipping a 10 item moves the gap by twice that amount. Then verify each income statement item reaches the cash flow statement, each balance sheet change is mirrored in cash flow with the correct sign, retained earnings roll forward correctly, and cash from the cash flow statement links to the balance sheet. Isolate by testing one line at a time.", c: ["Check whether the gap is constant or growing", "Halve the difference to find a sign error", "Verify every balance sheet change in cash flow", "Check retained earnings and cash links"], k: ["Systematic isolation beats guessing", "Opening balance sheet must itself balance"], m: ["Plugging the difference into cash"] },
  { t: "Valuation steps in a discounted cash flow", p: "Walk me through the steps of building an unlevered DCF valuation of a company.", d: 1, tp: "ib-valuation", i: "Project unlevered free cash flow for an explicit period of typically five to ten years from revenue, margins, taxes, capex and working capital. Calculate a terminal value, either by perpetuity growth or an exit multiple, at the end of the forecast. Discount each year's cash flow and the terminal value to present value at WACC to reach enterprise value. Then subtract net debt and other claims to get equity value, and divide by diluted shares for value per share. Finish with sensitivity analysis on WACC and terminal assumptions.", c: ["Project unlevered free cash flow", "Calculate terminal value", "Discount at WACC", "Bridge enterprise value to equity value"], k: ["Terminal value is a large share of total value", "Sensitivity analysis reflects uncertainty in the inputs"], m: ["Discounting unlevered cash flows at cost of equity"] },
  { t: "Enterprise value to equity value bridge", p: "How do you get from enterprise value to equity value, and why does each item belong?", d: 1, tp: "ib-valuation", i: "Equity value equals enterprise value minus debt, preferred stock and non-controlling interest, plus cash and investments. Enterprise value is the value of operations to all capital providers, so claims that rank ahead of or alongside common equity are subtracted, and non-operating assets such as cash are added because they were not generating the operating cash flows in the EV. Unfunded pension deficits and similar debt-like items are also deducted. Dividing by diluted shares gives value per share.", c: ["Subtract debt, preferred and non-controlling interest", "Add cash and investments", "Debt-like items such as pensions", "Divide by diluted shares for per-share value"], k: ["EV values operations; equity is the residual", "Cash is non-operating and added"], m: ["Subtracting cash instead of adding it when going to equity value"] },
  { t: "Choosing between EV/EBITDA and P/E", p: "When would you prefer EV/EBITDA to P/E for comparing companies, and what is the logic?", d: 1, tp: "ib-valuation", i: "EV/EBITDA is capital-structure neutral: both numerator and denominator are before the effect of interest, so highly levered and unlevered companies can be compared. P/E is a levered multiple, affected by interest costs, tax rates, depreciation policy and non-operating items, so it is good for comparing similarly levered firms, including financial companies. EV/EBITDA is preferred when leverage differs or when earnings are depressed or negative, but it overlooks capital intensity, so EV/EBIT can be used for capital-heavy businesses.", c: ["EV multiples are capital-structure neutral", "P/E is a levered equity metric", "Match numerator to denominator", "EBITDA ignores capex"], k: ["Pair enterprise value with pre-interest metrics", "Choose multiples that fit the industry's economics"], m: ["Dividing enterprise value by net income"] },
  { t: "CAPM and cost of equity", p: "Explain the CAPM formula and calculate the cost of equity with a 4 percent risk-free rate, a beta of 1.2 and an equity risk premium of 5.5 percent.", d: 1, tp: "ib-valuation", i: "CAPM states cost of equity equals risk-free rate plus beta times the equity risk premium. Here that is 4 percent plus 1.2 times 5.5 percent, or 10.6 percent. The risk-free rate is typically a long-term government bond yield, beta measures sensitivity to market movements, and the equity risk premium is the expected market return over the risk-free rate. Size or company-specific premiums are sometimes added for small firms.", c: ["Ke = rf + beta x ERP", "Risk-free rate from government bonds", "Beta measures systematic risk", "Result of 10.6 percent"], k: ["Only systematic risk is priced", "Inputs such as ERP are judgemental"], m: ["Using the market return instead of the risk premium"] },
  { t: "After-tax cost of debt", p: "How do you determine the cost of debt used in WACC, and why is it tax-effected?", d: 1, tp: "ib-valuation", i: "Use the current yield-to-maturity on the company's long-term debt, or a rate implied by its credit rating, rather than the historical coupon, since it reflects what the company would pay to borrow today. Interest is tax-deductible, so the effective cost is pre-tax cost times one minus the tax rate: 6 percent at a 25 percent tax rate gives 4.5 percent. The tax shield is thereby included in WACC rather than in the cash flows.", c: ["Current market yield, not coupon", "Multiply by (1 - tax rate)", "Interest tax deductibility", "Tax shield captured in WACC"], k: ["Marginal cost of new borrowing is relevant", "Avoid double counting the tax shield"], m: ["Using the coupon rate on old debt"] },
  { t: "Perpetuity growth terminal value", p: "How is terminal value calculated with the perpetuity growth method, and what is a reasonable growth rate?", d: 1, tp: "ib-valuation", i: "Terminal value at year N equals final-year free cash flow times one plus growth, divided by WACC minus growth. It values all cash flows beyond the forecast as a growing perpetuity. The growth rate should not exceed long-term nominal economic growth or inflation, usually about 2 to 3 percent in developed markets, because a company cannot outgrow the economy forever. The result is then discounted back to today with the same discount factor as year N.", c: ["TV = FCF x (1 + g) / (WACC - g)", "Growth below long-run nominal GDP", "WACC must exceed g", "Discount TV back from year N"], k: ["Small changes in g or WACC create large value changes", "Terminal year cash flow should be normalised"], m: ["Using a growth rate higher than WACC or GDP"] },
  { t: "Selecting comparable companies", p: "What criteria do you use to select a comparable company set for a trading comps analysis?", d: 1, tp: "ib-valuation", i: "Start with industry and business model, then screen for similar size, growth, profitability, geography, customer base and risk profile, and capital structure where relevant. Typically use around six to ten companies and review business descriptions and broker research. Remove outliers whose multiples are distorted by unusual events. The goal is companies the market would value on similar fundamentals, so that their multiples can be applied to the target.", c: ["Industry and business model", "Size, growth and margin similarity", "Geography and risk", "Remove outliers"], k: ["Comparability is about fundamentals, not just sector label", "Tiers of comps can be used when no perfect peers exist"], m: ["Picking comps only on industry code"] },
  { t: "Control premium in precedent transactions", p: "What is a control premium and how does it influence precedent transaction multiples?", d: 1, tp: "ib-valuation", i: "A control premium is the extra amount an acquirer pays over the unaffected market price for the ability to direct the company, capture synergies and gain full ownership, typically 20 to 40 percent for public targets. Precedent transaction multiples embed this premium, so they are generally higher than trading multiples, which reflect minority stakes with no control. The analysis uses multiples such as EV/EBITDA from completed deals in the sector to infer takeover value.", c: ["Premium over unaffected share price", "Pays for control and synergies", "Typically 20 to 40 percent", "Precedent multiples exceed trading multiples"], k: ["Trading comps are minority values", "Deal timing and market conditions matter"], m: ["Applying a control premium on top of precedent multiples again"] },
  { t: "Why discount free cash flow", p: "Why do we discount future cash flows, and why use WACC for unlevered free cash flow?", d: 1, tp: "ib-valuation", i: "Money received later is worth less today because of time value and risk: investors could earn a return elsewhere and future cash flows are uncertain. Unlevered free cash flow belongs to all capital providers, both debt and equity holders, so the appropriate rate is the blended required return on all capital, which is WACC. Discounting at WACC reflects the opportunity cost of the whole capital base, resulting in enterprise value.", c: ["Time value of money", "Risk compensation", "UFCF belongs to all capital providers", "WACC is the blended required return"], k: ["Discount rate must match the cash flow type", "Higher risk implies higher rate and lower value"], m: ["Using cost of equity for unlevered cash flows"] },
  { t: "Unlevered free cash flow build", p: "How do you calculate unlevered free cash flow from EBIT?", d: 1, tp: "ib-valuation", tp2: "ib-accounting", i: "Start with EBIT, subtract taxes on EBIT at the operating tax rate to get NOPAT, add back non-cash charges such as depreciation and amortisation, subtract capital expenditures, and subtract the increase in net working capital. Interest is excluded because the cash flow is before financing, so the figure is available to both lenders and shareholders. Stock compensation, if added back, should be treated consistently with how dilution is handled.", c: ["EBIT x (1 - tax rate)", "Add depreciation and amortisation", "Subtract capital expenditures", "Subtract increase in net working capital"], k: ["Excludes interest and financing effects", "Taxes are on unlevered operating profit"], m: ["Subtracting interest expense in UFCF"] },
  { t: "Why enterprise value excludes cash", p: "Why do we subtract cash when calculating enterprise value from equity value?", d: 1, tp: "ib-valuation", i: "Enterprise value measures the value of the core operating business. Cash is a non-operating asset, so it is excluded: buying the whole company means also receiving its cash, which could pay down debt, so the effective price of operations is lower. The metrics paired with EV, such as EBITDA, exclude interest income from cash, so leaving cash in EV would mismatch numerator and denominator. Hence EV equals equity value plus debt, preferred and minority interest, less cash.", c: ["Cash is non-operating", "Acquirer receives the cash", "Consistent with metrics excluding interest income", "EV = equity + debt + preferred + NCI - cash"], k: ["EV is the cost of operations alone", "Net debt is the key concept"], m: ["Thinking cash is part of operating value"] },
  { t: "Exit multiple versus perpetuity growth cross-check", p: "You estimate terminal value with a 10x EBITDA exit multiple. How would you sanity-check it against the perpetuity growth method?", d: 2, tp: "ib-valuation", i: "Compute the perpetuity growth rate implied by the exit multiple, and conversely the multiple implied by a chosen growth rate. With TV of 1,000 (10x EBITDA of 100), final-year FCF of 60 and WACC of 10 percent, implied g is (TV x WACC - FCF) / (TV + FCF) = (100 - 60) / 1,060, about 3.8 percent, which is aggressive versus long-run growth. Using g of 3 percent gives TV of about 883 and an implied multiple of roughly 8.8x. If the implied figures look unreasonable, revisit the exit multiple or the terminal assumptions.", c: ["Implied growth from exit multiple", "Implied multiple from perpetuity growth", "Formula g = (TV x WACC - FCF) / (TV + FCF)", "Compare to long-run growth and market multiples"], k: ["Exit multiples embed market-based expectations", "Perpetuity growth is intrinsic but sensitive"], m: ["Using an exit multiple from today's high-growth peers without testing the implied growth"] },
  { t: "Mid-year convention", p: "What is the mid-year convention in a DCF and how does it affect terminal value discounting?", d: 2, tp: "ib-valuation", i: "It assumes cash flows arrive evenly through each year rather than at year end, so year one is discounted 0.5 years, year two 1.5 years and so on, which raises the valuation modestly. For terminal value, the perpetuity growth method uses the mid-year convention too, discounting TV at N minus 0.5 (equivalently multiplying by one plus WACC to the power 0.5), because the perpetuity of mid-year cash flows is consistent with that timing. An exit multiple TV represents a sale at year end, so it is discounted at the full N years.", c: ["Cash flows discounted at 0.5, 1.5, 2.5 years", "Raises valuation", "Perpetuity growth TV uses N - 0.5", "Exit multiple TV discounted at N"], k: ["Reflects cash received through the year", "Terminal methods differ because of timing assumptions"], m: ["Applying mid-year discounting to the exit multiple terminal value"] },
  { t: "WACC calculation walkthrough", p: "A company has 70 of equity and 30 of debt at market value, a 10.6 percent cost of equity, 6 percent pre-tax cost of debt and 25 percent tax rate. Walk me through its WACC.", d: 2, tp: "ib-valuation", i: "WACC equals equity weight times cost of equity plus debt weight times after-tax cost of debt. Equity weight is 70 percent, debt weight 30 percent, and after-tax cost of debt is 6 percent times 0.75, or 4.5 percent. So WACC is 0.7 times 10.6 percent (7.42 percent) plus 0.3 times 4.5 percent (1.35 percent), about 8.77 percent. Weights should use market values and the target capital structure, often drawn from peer companies, rather than book values.", c: ["WACC = E/V x Ke + D/V x Kd x (1 - t)", "After-tax Kd is 4.5 percent", "Market value weights", "Result about 8.77 percent"], k: ["Target capital structure is the relevant mix", "WACC reflects the opportunity cost of all capital"], m: ["Using book value of equity for weights"] },
  { t: "Unlevering and relevering beta", p: "Why do you unlever betas of comparable companies and relever them, and how is it done?", d: 2, tp: "ib-valuation", i: "Observed beta reflects both business risk and the financial risk from leverage, so peers with different debt levels cannot be compared directly. Unlevered beta equals levered beta divided by one plus (1 - tax rate) times debt/equity. For a levered beta of 1.2, D/E of 0.5 and 25 percent tax, unlevered beta is 1.2 / 1.375 = 0.87. Take the median across peers and relever at the target's capital structure, for instance D/E of 0.25 gives 0.87 x 1.1875 = 1.04, then use that in CAPM.", c: ["Remove capital structure effect", "Unlevered = levered / (1 + (1 - t) x D/E)", "Take peer median", "Relever at target D/E"], k: ["Isolate business risk from financial risk", "Target capital structure sets final beta"], m: ["Averaging raw levered betas of firms with different leverage"] },
  { t: "Why precedents often exceed trading comps", p: "Why do precedent transaction valuations frequently exceed trading comps valuation, and when might the opposite be true?", d: 2, tp: "ib-valuation", i: "Precedents include a control premium and the value of synergies that buyers are willing to pay, while trading comps reflect minority marketable positions. So precedent multiples are usually higher. The opposite can occur when deals were struck in depressed markets, when the transactions were distressed or involved small businesses, or when current public markets are at elevated levels relative to the period of the deals. Dated precedents may not reflect today's multiples or interest rates.", c: ["Control premium", "Synergies in price", "Minority versus control basis", "Market timing and distress can reverse it"], k: ["Interpret multiples with context", "Recency and comparability of deals matter"], m: ["Assuming precedents always give the highest value"] },
  { t: "Valuing a company with negative free cash flow", p: "How would you value a high-growth company that has negative free cash flow today?", d: 2, tp: "ib-valuation", i: "A standard DCF with a short horizon fails because most value sits beyond the near term. Options are extending the explicit forecast until the company reaches steady margins and positive cash flow, then applying a terminal value on normalised metrics, and discounting at a higher rate for risk. Alternatively use revenue or other operating-metric multiples (EV/Revenue, EV/ARR), precedent deals, or scenario-weighted valuations. Also consider funding needs and dilution, since the company must raise cash before reaching profitability.", c: ["Extend the forecast to a steady state", "Normalised terminal margins", "Revenue-based multiples", "Funding needs and dilution"], k: ["Terminal value dominates and needs care", "Scenario analysis reflects binary outcomes"], m: ["Applying EV/EBITDA to negative EBITDA"] },
  { t: "Operating leases and enterprise value consistency", p: "How should lease liabilities be handled when calculating enterprise value and multiples for companies reporting under IFRS 16 versus US GAAP?", d: 2, tp: "ib-valuation", tp2: "ib-accounting", i: "The rule is consistency between EV and the earnings metric. Under IFRS 16 lease cost is depreciation and interest, so EBITDA excludes rent and the lease liability should be included in net debt. Under US GAAP operating leases, rent remains inside operating expense, so EBITDA is after rent and the operating lease liability should be excluded from EV. Comparing across the two regimes requires adjusting one set, for example by deducting lease costs from IFRS EBITDA or adding lease liabilities for all companies.", c: ["Lease treatment must match between EV and EBITDA", "IFRS 16 EBITDA is before lease cost", "US GAAP operating lease rent stays in EBITDA", "Adjust for cross-regime comparability"], k: ["Mismatch overstates or understates multiples", "Lease liabilities are debt-like"], m: ["Including lease debt in EV but using post-rent EBITDA"] },
  { t: "Diluted shares and the treasury stock method", p: "How do you calculate diluted shares outstanding with options, using the treasury stock method?", d: 2, tp: "ib-valuation", i: "Start with basic shares and add in-the-money dilutive securities. For options, assume exercise proceeds are used to buy back shares at the current price, so net new shares equal options minus proceeds divided by share price. With 10 million options at a 20 strike and a 30 share price, proceeds are 200 million and 6.67 million shares are repurchased, adding 3.33 million shares. Out-of-the-money options are excluded. Convertibles are added if in the money. In a DCF, the share price depends on equity value, which can require circular iteration.", c: ["Count only in-the-money options", "Proceeds repurchase shares at current price", "Net new shares equals options x (1 - strike/price)", "Include in-the-money convertibles"], k: ["Dilution rises with the share price", "Per-share value and share count are circular in DCF"], m: ["Adding all options without netting the repurchase"] },
  { t: "Calendarisation of financials for comps", p: "What is calendarisation, and why would you do it when building a comps table?", d: 2, tp: "ib-valuation", i: "Companies have different fiscal year ends, so their annual figures cover different periods. Calendarisation adjusts results to a common period, usually the calendar year, by weighting fiscal years. For a company with a June year-end, calendar-year earnings equal roughly half of the fiscal year ending in June of that year plus half of the following fiscal year. Using it ensures multiples are on a comparable timeframe, along with LTM and forward estimates, preventing distortions in fast-growing or seasonal businesses.", c: ["Different fiscal year ends", "Weighted blend of fiscal years", "June year-end example uses 50/50", "Comparable LTM and forward multiples"], k: ["Time alignment matters most with high growth", "Use consistent forecast sources"], m: ["Comparing fiscal-year numbers directly across companies"] },
  { t: "Choosing multiples by industry", p: "Which valuation metrics would you use for a bank, a REIT, a software company and an oil and gas producer, and why?", d: 2, tp: "ib-valuation", i: "Banks use P/E and price to tangible book value because debt is an operating input and EV is not meaningful. REITs use price to FFO or AFFO and net asset value, because real estate depreciation distorts earnings. Software firms often use EV/Revenue or EV/ARR for growth names, shifting to EV/EBITDA or free cash flow as they mature. Oil and gas producers use EV/EBITDAX, EV per flowing barrel and NAV based on reserves, since exploration expense and reserves drive value.", c: ["Banks: P/E and P/TBV", "REITs: P/FFO and NAV", "Software: EV/Revenue or ARR", "Energy: EV/EBITDAX and reserves-based NAV"], k: ["Metrics should capture the industry's economic drivers", "Accounting distortions determine the metric"], m: ["Using EV/EBITDA for banks"] },
  { t: "DCF sensitivity to WACC and growth", p: "Why is a DCF so sensitive to the WACC and terminal growth assumptions, and how do you present that?", d: 2, tp: "ib-valuation", i: "Terminal value is typically 60 to 80 percent of enterprise value and depends on the denominator WACC minus g. A small change in either shifts that spread proportionally a lot: moving WACC from 9 to 10 percent with 3 percent growth changes the spread from 6 to 7 percent, reducing terminal value by about 14 percent. Present the result as sensitivity tables, such as WACC against terminal growth or exit multiple, football field ranges, and scenario cases rather than a single point estimate.", c: ["Terminal value is the bulk of value", "Spread of WACC minus g", "Sensitivity tables", "Present ranges, not point estimates"], k: ["Precision is false when inputs are uncertain", "Sanity check against comps"], m: ["Treating the DCF output as exact"] },
  { t: "Share of value from terminal value", p: "In a five-year DCF, terminal value makes up 85 percent of enterprise value. What does that tell you and how might you respond?", d: 2, tp: "ib-valuation", i: "It signals that the valuation relies heavily on assumptions about the distant future, so it is fragile and driven by WACC, growth or the exit multiple. A typical range is 60 to 80 percent for a five-year forecast. Responses include lengthening the explicit forecast so the company reaches steady state, normalising terminal-year margins, capex and working capital, cross-checking the implied multiple or growth, and showing wide sensitivities. For fast-growing firms a longer forecast with a fade period is more credible.", c: ["High reliance on terminal assumptions", "Typical share is 60 to 80 percent", "Extend forecast or add fade period", "Cross-check implied multiple and growth"], k: ["A short forecast for a high-growth company puts too much in TV", "Normalise terminal year metrics"], m: ["Ignoring terminal value share as a quality check"] },
  { t: "Net debt and debt-like items", p: "What items beyond financial debt and cash might you include when calculating net debt for an equity bridge?", d: 2, tp: "ib-valuation", tp2: "ib-accounting", i: "Beyond borrowings and cash, include preferred stock, non-controlling interests, finance and (where consistent) operating lease liabilities, unfunded pension and post-retirement deficits (often tax-effected), capital-like obligations such as deferred consideration and, for some analysts, large restructuring or litigation provisions. Equity-method investments and other non-operating assets are added. Trapped cash may be discounted. All items must be consistent with how the EBITDA or multiple is defined.", c: ["Preferred stock and non-controlling interest", "Lease liabilities consistent with EBITDA", "Pension deficits", "Add equity investments and non-operating assets"], k: ["Anything ranking ahead of common equity is debt-like", "Consistency with the metric is crucial"], m: ["Using only bank debt in the bridge"] },
  { t: "Sum-of-the-parts valuation", p: "When is a sum-of-the-parts valuation appropriate, and what are the main pitfalls?", d: 2, tp: "ib-valuation", i: "It suits conglomerates or companies with segments in different industries and different growth and risk profiles, where one blended multiple would misprice them. Value each segment with its own peers or DCF, add the segment enterprise values, subtract net debt and other claims, and allocate corporate costs. Pitfalls include unallocated headquarters costs, inter-segment transactions, tax leakage on separation, and the conglomerate discount that markets may apply, which means the sum may exceed the market value.", c: ["Different segments valued separately", "Add segment EVs", "Allocate corporate overhead", "Conglomerate discount and tax leakage"], k: ["Segment-specific multiples improve accuracy", "Sum may not be realisable"], m: ["Ignoring corporate costs"] },
  { t: "Implied perpetuity growth rate calculation", p: "Given a terminal value of 1,200, final-year FCF of 70 and a WACC of 9 percent, derive the implied perpetuity growth rate and judge whether it is sensible.", d: 3, tp: "ib-valuation", i: "Rearrange TV = FCF x (1 + g) / (WACC - g) to get g = (TV x WACC - FCF) / (TV + FCF). So g = (1,200 x 0.09 - 70) / (1,270) = 38 / 1,270, about 3.0 percent. That is at the upper end of reasonable long-run nominal growth in developed markets, so the terminal value is defensible but offers little cushion. A figure above long-term GDP or inflation would suggest the exit multiple is too rich.", c: ["g = (TV x WACC - FCF) / (TV + FCF)", "Result about 3 percent", "Compare to long-run nominal growth", "Little cushion at the top of range"], k: ["Back-solving tests multiple reasonableness", "Terminal cash flow base matters"], m: ["Using the formula with FCF already grown by (1 + g)"] },
  { t: "Capital structure and WACC", p: "Does adding debt always lower WACC and increase firm value? Discuss with Modigliani-Miller.", d: 3, tp: "ib-valuation", i: "Without taxes or distress costs, Modigliani-Miller says value is independent of capital structure: cheaper debt is offset by a higher cost of equity as leverage raises equity risk, so WACC is constant. With taxes, interest deductibility creates a tax shield, lowering after-tax cost of debt and WACC and adding value. But as leverage rises, the probability and cost of financial distress, agency costs and rising cost of debt offset the shield, so there is an optimal structure where WACC is minimised. Beyond it, more debt reduces value.", c: ["MM without taxes: irrelevance", "Tax shield lowers WACC", "Distress costs offset benefits", "Optimal capital structure"], k: ["Cost of equity rises with leverage", "Trade-off theory explains the optimum"], m: ["Thinking cheaper debt alone lowers WACC"] },
  { t: "Cost of equity for a small private company", p: "How would you estimate the cost of equity for a small private company with no traded shares?", d: 3, tp: "ib-valuation", i: "Use CAPM with a beta taken from public comparables: unlever each peer's beta, take a median, and relever at the target's expected capital structure. Add a size premium for small firms and, where justified, a company-specific risk premium for concentration, key-person dependence or weak diversification. Some practitioners add a discount for lack of marketability to the final equity value rather than the rate. Cross-check with build-up methods and sector returns expected by investors such as private equity.", c: ["Peer betas unlevered and relevered", "Size premium", "Company-specific risk premium", "Marketability discount treatment"], k: ["Private company has no observable beta", "Avoid double counting illiquidity"], m: ["Using the company's own accounting returns as beta"] },
  { t: "Terminal value for a declining business", p: "How would you handle terminal value for a business in secular decline?", d: 3, tp: "ib-valuation", i: "The perpetuity growth method can use a negative growth rate, such as minus 2 percent, giving a lower terminal value than a stable-growth assumption. Alternatively model a fade period over which cash flows decline, ensure capex and reinvestment fall as the business shrinks, or value it as a run-off or liquidation scenario with asset sales. An exit multiple should reflect low multiples seen for declining peers, not market averages. Cash harvesting, so FCF can exceed earnings as capex drops, should be reflected.", c: ["Negative terminal growth rate", "Run-off or liquidation value", "Exit multiple from declining peers", "Reinvestment falls as business shrinks"], k: ["Perpetual growth is not assumed", "Realistic end-of-life cash flows"], m: ["Using a positive 2 to 3 percent perpetual growth by default"] },
  { t: "LBO analysis as a valuation floor", p: "How does a leveraged buyout analysis help frame valuation, and why is it often called a floor?", d: 3, tp: "ib-valuation", i: "An LBO analysis solves for the price a financial sponsor could pay to achieve a target return, commonly 20 to 25 percent IRR, given assumptions about debt capacity, operating performance and exit multiple. Since sponsors have no synergies and rely on leverage, this price usually sits below what strategic acquirers can pay, so it is seen as a floor for a sale process. Key drivers are leverage multiples, interest costs, free cash flow for debt paydown, exit timing and exit multiple.", c: ["Solve for price at target IRR", "Debt capacity and cash flow paydown", "Exit multiple and timing", "Sponsors lack synergies"], k: ["Ability-to-pay analysis", "Credit markets constrain results"], m: ["Treating the LBO value as the ceiling"] },
  { t: "Convertible securities in equity value", p: "How do you treat a convertible bond when computing diluted equity value and enterprise value?", d: 3, tp: "ib-valuation", i: "Compare the share price to the conversion price. If the stock trades above conversion, the convertible is in the money: treat it as equity, add the new shares from conversion to the diluted share count and exclude the debt from net debt. If it is below the conversion price, treat it as debt at face value and do not add shares. The decision must be consistent so the instrument is not counted twice. In a DCF, the implied share price determines whether conversion is rational, adding circularity.", c: ["Compare price with conversion price", "In the money: add shares, remove debt", "Out of the money: treat as debt", "Avoid double counting"], k: ["Instrument is hybrid, treat according to moneyness", "Circular with implied price"], m: ["Counting both the debt and the converted shares"] },
  { t: "Adjusted present value versus WACC DCF", p: "When would you use an adjusted present value (APV) approach rather than a WACC-based DCF?", d: 3, tp: "ib-valuation", i: "APV values the business as if unlevered, discounting free cash flow at the unlevered cost of equity, then adds the present value of financing side effects, mainly interest tax shields, at a rate reflecting their risk. It is most useful when capital structure changes materially over time, such as in an LBO with scheduled debt paydown, where a constant-weight WACC would be inaccurate. WACC is simpler and works when the target capital structure is stable. APV also makes the value of the tax shield explicit.", c: ["Unlevered value plus PV of tax shields", "Discount unlevered FCF at unlevered Ke", "Suits changing capital structure", "WACC assumes stable target weights"], k: ["Separates operating value from financing value", "Tax shield discount rate is a judgement"], m: ["Using the same WACC when leverage is falling quickly"] },
  { t: "Consistency of currency and inflation in a DCF", p: "You are valuing a company with cash flows in a high-inflation emerging market currency but investors think in US dollars. How do you keep the DCF consistent?", d: 3, tp: "ib-valuation", i: "Cash flows and the discount rate must be in the same currency and either both nominal or both real. Option one is to forecast in local currency, use a local-currency discount rate (US rate adjusted for the inflation differential, plus country risk), then convert the resulting value at spot. Option two is to forecast in dollars using forward-rate or inflation-parity projections and discount at a dollar rate with country risk premium. Mixing a dollar discount rate with local nominal cash flows overstates value. Terminal growth should also be consistent with inflation in that currency.", c: ["Match currency of cash flows and discount rate", "Nominal with nominal", "Adjust for inflation differential", "Country risk premium"], k: ["Value should be about equal under both approaches", "Terminal growth reflects local inflation"], m: ["Discounting local-currency nominal cash flows at a dollar rate"] },
  { t: "Valuation date between fiscal year ends and stub periods", p: "If you are valuing a company at 30 September and its fiscal year ends in December, how do you handle the first-year cash flow and discounting?", d: 3, tp: "ib-valuation", i: "Use a stub period. Only the cash flow from the valuation date to the fiscal year-end belongs to the buyer, so scale the first year's free cash flow by the fraction remaining, here 0.25 of the year. Discount that stub cash flow by the stub fraction (or half of it under mid-period convention), and discount later years at the stub plus whole years, so year two is 1.25 years. Net debt and share count should be taken at or near the valuation date. Terminal value is discounted using the final period's timing.", c: ["Prorate the first-year cash flow", "Adjust discount periods by stub fraction", "Later periods are stub plus whole years", "Use balance sheet at valuation date"], k: ["Avoids paying for cash already earned by prior owners", "Timing consistency in discount factors"], m: ["Discounting a full first-year cash flow from a mid-year valuation date"] },
  { t: "Cash taxes versus book taxes", p: "A company's book tax expense is 50 but it paid only 38 in cash taxes this year. Explain the possible causes and where the 12 shows up in the statements.", d: 3, tp: "ib-accounting", i: "The gap is a timing difference, most often accelerated tax depreciation, but also NOL usage, deferred revenue taxed on receipt, or stock option deductions. Book tax expense is split into current tax (cash) of 38 and deferred tax of 12. The 12 increases a deferred tax liability (or reduces a deferred tax asset) on the balance sheet, and appears in cash from operations as a deferred tax add-back because it reduced cash taxes without reducing book tax expense. If the differences reverse later, cash taxes will exceed book taxes. For valuation, use cash taxes or model the DTL path explicitly.", c: ["Current versus deferred tax expense", "Temporary timing differences", "Deferred tax add-back in operating cash flow", "DTL or DTA on the balance sheet"], k: ["Book tax is accrual-based, cash tax is what is paid", "Persistent growth can make the deferral long-lasting"], m: ["Assuming the 12 is a permanent saving"] },
  { t: "Calculating equity value per share from enterprise value", p: "A DCF gives an enterprise value of 2,000. The company has 500 of debt, 100 of cash, 50 of preferred stock and 20 million diluted shares. What is the value per share and what could change it?", d: 2, tp: "ib-valuation", i: "Equity value is 2,000 minus 500 of debt minus 50 of preferred plus 100 of cash, which is 1,550. Dividing by 20 million diluted shares gives 77.50 per share. The diluted count depends on the share price through options and convertibles, so a higher implied price adds shares and lowers the value per share slightly, requiring iteration. Adding items such as pension deficits or non-controlling interests would reduce equity value, while equity-method investments would raise it.", c: ["Equity = EV - debt - preferred + cash", "Equity value of 1,550", "Per share value of 77.50", "Diluted share count circularity"], k: ["Every claim ahead of common equity is deducted", "Dilution depends on implied price"], m: ["Adding debt instead of subtracting it"] },
];
